// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // 1. set up specific scenario: any amount will do, choose 5
        uint256 amount = 5;
        // 2. call AdjustBetAmounts — it's onlyOwner, and owner is address(this) from setUp (since msg.sender in constructor is tx.origin, which is this test contract)
        c.AdjustBetAmounts(amount);
        // 3. assert that betLimit equals amount (reference behavior) — mutant would set it to amount+1
        assertTrue(c.currentBetLimit() == amount);
    }
}

