pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // 1. Open to the public
        c.OpenToThePublic();
        // 2. Adjust bet limit to 5
        c.AdjustBetAmounts(5);
        // 3. Fund and prank a real account (tx.origin == msg.sender)
        address player = address(0x1234);
        vm.deal(player, 5 ether);
        vm.prank(player, player);
        // 4. Try to wager with exactly 5 wei
        bool success;
        try c.wager{value: 5}() {
            success = true;
        } catch {
            success = false;
        }
        // Reference: betLimit == 5, so wager(5) succeeds → success true
        // Mutant: betLimit == 6, so wager(5) reverts → success false
        assertTrue(success);
    }
}

