pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // 1. Deploy: owner = address(this), betLimit initially 0
        // 2. Open to public so wager() works
        c.OpenToThePublic();
        // 3. Owner calls AdjustBetAmounts(100)
        c.AdjustBetAmounts(100);
        // 4. Owner tries to wager with 0 wei (match P's betLimit=100 fails, M's betLimit=0 works)
        //    For P: require(msg.value == betLimit) means betLimit=100, msg.value=0 fails -> revert
        //    For M: betLimit=0, msg.value=0 passes -> no revert
        // Use try/catch to catch revert
        bool ok;
        vm.deal(address(this), 0);
        vm.prank(address(this));
        try c.wager{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference (P) reverts (ok false), bug (M) succeeds (ok true) => assertFalse(ok) (P asserts true for ok==false)
        assertTrue(!ok);
    }
}

