pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // First, call OpenToThePublic() as owner
        c.OpenToThePublic();

        // Now try to wager as a non-owner (address(this) is the original caller, but after setUp we are still the owner? Actually deployer is address(this), so we need a different user)
        address player = address(0x1);
        vm.deal(player, 1 ether);

        // In the reference version, openToPublic is true so wager() succeeds
        // In the buggy version, openToPublic is still false so wager() reverts
        bool ok;
        vm.prank(player);
        c.wager{value: 0}(); // betLimit is 0, so msg.value == 0 works
        // If we reached here, no revert — reference version passes, buggy version would revert
        ok = true;

        // But to detect divergence, we need to check that a subsequent call doesn't fail
        // Actually simpler: just assert that the player's wager is now > 0 (reference)
        // or use a try/catch around the wager call
        // Let's redo with try/catch:
        vm.prank(player);
        try c.wager{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

