pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Step 1: Call OpenToThePublic to set openToPublic = true (reference) or do nothing (bug)
        c.OpenToThePublic();
        // Step 2: Call AdjustBetAmounts – the difference manifests after this call
        c.AdjustBetAmounts(100);
        // Step 3: Check openToPublic via OpenToThePublic's effect – the only public way is via wager behavior
        // But wager requires openToPublic true. Instead, we observe the revert behavior of wager:
        // For the reference, openToPublic is true, wager should revert due to betLimit mismatch (0 != 100)
        // Actually wager requires msg.value == betLimit, and betLimit is now 100, we call with 100
        // For the bug, openToPublic is false, wager reverts with isOpenToPublic modifier
        vm.deal(address(this), 100);
        vm.prank(address(this));
        bool ok = address(this).call{value: 100}(abi.encodeWithSignature("wager()"));
        // Reference: wager succeeds (no revert) because openToPublic true and value == betLimit
        // Bug: wager reverts because openToPublic false
        assertTrue(ok, "wager should succeed (reference) but bug reverts");
    }
}

